function App() {
  return (
    <div style={{ textAlign: "center", padding: "2rem" }}>
      <h1>fashion Dux images</h1>
      <p>Drop your product images into <code>/public/images</code> folder</p>
      <p>Then access them like:</p>
      <code>https://your-app.vercel.app/images/W101_black.jpg</code>
    </div>
  );
}

export default App;
